const http = require('http');
const WebSocket = require('ws');
const crypto = require('crypto');
const ffi = require('ffi-napi');
const ref = require('ref-napi');
const path = require('path');

// Native message processing library for performance-critical path
// Compiled from C with JNI-style interface for message sanitization
const NATIVE_LIB_PATH = process.env.NATIVE_LIB_PATH || '/opt/chat/lib/libmsgproc';

const StringPtr = ref.refType(ref.types.CString);

const libmsgproc = ffi.Library(NATIVE_LIB_PATH, {
  'msg_sanitize': ['int', ['string', 'pointer', 'int']],
  'msg_get_buffer_size': ['int', ['string']],
  'msg_init_context': ['pointer', []],
  'msg_free_context': ['void', ['pointer']]
});

class MessageProcessor {
  constructor() {
    this.ctx = libmsgproc.msg_init_context();
    this.maxMsgLen = 4096;
  }

  sanitize(rawMessage) {
    // Enforce maximum message length before native processing
    if (Buffer.byteLength(rawMessage, 'utf8') > this.maxMsgLen) {
      throw new Error('Message too long');
    }

    // Get required buffer size from native lib
    const requiredSize = libmsgproc.msg_get_buffer_size(rawMessage);

    // Allocate output buffer based on native library's size calculation
    const outBuf = Buffer.alloc(requiredSize);

    // Call native sanitizer - pass actual byte length as bound
    // This ensures the native lib knows the true buffer constraint
    const result = libmsgproc.msg_sanitize(
      rawMessage,
      outBuf,
      Buffer.byteLength(rawMessage, 'utf8')  // Actual UTF-8 byte length
    );

    if (result < 0) {
      throw new Error('Native sanitization failed');
    }

    return outBuf.toString('utf8', 0, result);
  }

  destroy() {
    if (this.ctx) {
      libmsgproc.msg_free_context(this.ctx);
      this.ctx = null;
    }
  }
}

// Chat room state
const rooms = new Map();
const sessions = new Map();
const processor = new MessageProcessor();

// Server secret used to verify signed authentication tokens.
// Must be provided via environment in production.
const AUTH_SECRET = process.env.AUTH_SECRET;
if (!AUTH_SECRET) {
  throw new Error('AUTH_SECRET environment variable is required');
}

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

function constantTimeEquals(a, b) {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  if (ab.length !== bb.length) return false;
  return crypto.timingSafeEqual(ab, bb);
}

function authenticateToken(token) {
  // Token format: base64url(payload).base64url(hmacSHA256(payload, secret))
  // The signature is verified with the server secret before trusting any
  // user identity contained in the payload.
  if (!token || typeof token !== 'string') return null;
  if (token.length < 16 || token.length > 4096) return null;

  const parts = token.split('.');
  if (parts.length !== 2) return null;

  const [payloadPart, sigPart] = parts;
  if (!payloadPart || !sigPart) return null;

  const expectedSig = crypto
    .createHmac('sha256', AUTH_SECRET)
    .update(payloadPart)
    .digest('base64url');

  if (!constantTimeEquals(sigPart, expectedSig)) return null;

  let decoded;
  try {
    decoded = Buffer.from(payloadPart, 'base64url');
  } catch (e) {
    return null;
  }
  if (decoded.length < 12) return null;

  // Extract user ID from verified token payload
  const userId = decoded
    .toString('utf8', 0, Math.min(decoded.length, 64))
    .replace(/[^a-zA-Z0-9_-]/g, '');
  return userId || null;
}

const server = http.createServer((req, res) => {
  if (req.url === '/healthz') {
    res.writeHead(200);
    res.end('ok');
  } else {
    res.writeHead(404);
    res.end();
  }
});

const wss = new WebSocket.Server({ server });

wss.on('connection', (ws, req) => {
  const token = new URL(req.url, 'http://localhost').searchParams.get('token');
  const userId = authenticateToken(token);

  if (!userId) {
    ws.close(4001, 'Unauthorized');
    return;
  }

  const sessionId = generateSessionId();
  sessions.set(sessionId, { userId, ws, rooms: new Set() });

  ws.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString());
      handleMessage(sessionId, msg);
    } catch (e) {
      ws.send(JSON.stringify({ error: 'Invalid message format' }));
    }
  });

  ws.on('close', () => {
    const session = sessions.get(sessionId);
    if (session) {
      session.rooms.forEach(room => leaveRoom(sessionId, room));
      sessions.delete(sessionId);
    }
  });

  ws.send(JSON.stringify({ type: 'connected', sessionId }));
});

function handleMessage(sessionId, msg) {
  const session = sessions.get(sessionId);
  if (!session) return;

  switch (msg.type) {
    case 'join':
      joinRoom(sessionId, msg.room);
      break;
    case 'leave':
      leaveRoom(sessionId, msg.room);
      break;
    case 'chat':
      broadcastChat(sessionId, msg.room, msg.content);
      break;
  }
}

function joinRoom(sessionId, roomName) {
  if (!roomName || typeof roomName !== 'string') return;
  const sanitizedRoom = roomName.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);
  if (!sanitizedRoom) return;

  if (!rooms.has(sanitizedRoom)) {
    rooms.set(sanitizedRoom, new Set());
  }
  rooms.get(sanitizedRoom).add(sessionId);
  sessions.get(sessionId).rooms.add(sanitizedRoom);
}

function leaveRoom(sessionId, roomName) {
  if (!roomName || typeof roomName !== 'string') return;
  const sanitizedRoom = roomName.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);

  const room = rooms.get(sanitizedRoom);
  if (room) {
    room.delete(sessionId);
    if (room.size === 0) rooms.delete(sanitizedRoom);
  }
  const session = sessions.get(sessionId);
  if (session) session.rooms.delete(sanitizedRoom);
}

function broadcastChat(sessionId, roomName, content) {
  const session = sessions.get(sessionId);
  if (!session || !content || typeof content !== 'string') return;

  if (!roomName || typeof roomName !== 'string') return;
  const sanitizedRoom = roomName.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 32);
  if (!session.rooms.has(sanitizedRoom)) return;

  // Use native processor for high-performance sanitization
  let sanitizedContent;
  try {
    sanitizedContent = processor.sanitize(content);
  } catch (e) {
    session.ws.send(JSON.stringify({ error: 'Message processing failed' }));
    return;
  }

  const outMsg = JSON.stringify({
    type: 'chat',
    room: sanitizedRoom,
    from: session.userId,
    content: sanitizedContent,
    ts: Date.now()
  });

  const room = rooms.get(sanitizedRoom);
  if (room) {
    room.forEach(sid => {
      const s = sessions.get(sid);
      if (s && s.ws.readyState === WebSocket.OPEN) {
        s.ws.send(outMsg);
      }
    });
  }
}

const PORT = parseInt(process.env.CHAT_PORT) || 8080;
server.listen(PORT, '0.0.0.0', () => {
  console.log(`Chat server listening on port ${PORT}`);
});

process.on('SIGTERM', () => {
  processor.destroy();
  wss.close();
  server.close();
});

module.exports = { server, wss };
